
import * as THREE from
  "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js";

  export class Water {
    constructor(scene) {
        this.uniforms = {
              uTime: { value: 0 },
                    uFogColor: {
                            value: new THREE.Color("#071522")
                                  }
                                      };

                                          const geometry = new THREE.PlaneGeometry(
                                                2000,
                                                      2000,
                                                            256,
                                                                  256
                                                                      );

                                                                          const material = new THREE.ShaderMaterial({
                                                                                uniforms: this.uniforms,

                                                                                      vertexShader: `
                                                                                              uniform float uTime;

                                                                                                      varying vec2 vUv;
                                                                                                              varying vec3 vWorldPosition;
                                                                                                                      varying vec3 vNormal;

                                                                                                                              float waveHeight(vec2 p) {
                                                                                                                                        float t = uTime;

                                                                                                                                                  float wave1 = sin(p.x * 0.035 + t * 0.7) * 0.22;
                                                                                                                                                            float wave2 = sin(p.y * 0.052 - t * 0.5) * 0.12;
                                                                                                                                                                      float wave3 = sin((p.x + p.y) * 0.025 + t * 0.35) * 0.18;
                                                                                                                                                                                float wave4 = sin((p.x - p.y) * 0.018 - t * 0.25) * 0.10;

                                                                                                                                                                                          return wave1 + wave2 + wave3 + wave4;
                                                                                                                                                                                                  }

                                                                                                                                                                                                          void main() {
                                                                                                                                                                                                                    vUv = uv;

                                                                                                                                                                                                                              vec3 pos = position;

                                                                                                                                                                                                                                        vec2 p = pos.xy;

                                                                                                                                                                                                                                                  float height = waveHeight(p);
                                                                                                                                                                                                                                                            pos.z += height;

                                                                                                                                                                                                                                                                      float e = 0.5;

                                                                                                                                                                                                                                                                                float dx =
                                                                                                                                                                                                                                                                                            waveHeight(p + vec2(e, 0.0)) -
                                                                                                                                                                                                                                                                                                        waveHeight(p - vec2(e, 0.0));

                                                                                                                                                                                                                                                                                                                  float dy =
                                                                                                                                                                                                                                                                                                                              waveHeight(p + vec2(0.0, e)) -
                                                                                                                                                                                                                                                                                                                                          waveHeight(p - vec2(0.0, e));

                                                                                                                                                                                                                                                                                                                                                    vec3 localNormal = normalize(
                                                                                                                                                                                                                                                                                                                                                                vec3(-dx / (2.0 * e), -dy / (2.0 * e), 1.0)
                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                    vNormal = normalize(normalMatrix * localNormal);

                                                                                                                                                                                                                                                                                                                                                                                              vec4 worldPosition =
                                                                                                                                                                                                                                                                                                                                                                                                          modelMatrix * vec4(pos, 1.0);

                                                                                                                                                                                                                                                                                                                                                                                                                    vWorldPosition = worldPosition.xyz;

                                                                                                                                                                                                                                                                                                                                                                                                                              gl_Position =
                                                                                                                                                                                                                                                                                                                                                                                                                                          projectionMatrix *
                                                                                                                                                                                                                                                                                                                                                                                                                                                      viewMatrix *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  worldPosition;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fragmentShader: `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              uniform float uTime;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      uniform vec3 uFogColor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              varying vec2 vUv;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      varying vec3 vWorldPosition;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              varying vec3 vNormal;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      void main() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                vec3 normal = normalize(vNormal);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          vec3 viewDirection = normalize(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cameraPosition - vWorldPosition
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          vec3 lightDirection = normalize(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      vec3(-0.4, 0.8, 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          float diffuse = max(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dot(normal, lightDirection),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  0.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      float fresnel = pow(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  1.0 - max(dot(normal, viewDirection), 0.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              3.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  vec3 deepColor = vec3(0.008, 0.035, 0.075);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            vec3 blueColor = vec3(0.015, 0.105, 0.17);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      vec3 cyanColor = vec3(0.10, 0.34, 0.42);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                vec3 waterColor = mix(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            deepColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        blueColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    diffuse * 0.65 + 0.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        waterColor = mix(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    waterColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cyanColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fresnel * 0.55
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                float glintPattern = sin(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            vWorldPosition.x * 0.18 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        vWorldPosition.z * 0.12 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    uTime * 0.9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        float glints = smoothstep(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    0.94,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                1.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            glintPattern
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                float highlights = pow(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            max(dot(reflect(-lightDirection, normal), viewDirection), 0.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        48.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            waterColor += vec3(0.18, 0.48, 0.58) * glints * 0.22;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      waterColor += vec3(0.35, 0.65, 0.8) * highlights * 0.5;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                float distanceFromCamera = distance(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cameraPosition,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        vWorldPosition
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float fog = 1.0 - exp(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -distanceFromCamera * 0.009
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            waterColor = mix(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        waterColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    uFogColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                clamp(fog, 0.0, 0.88)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gl_FragColor = vec4(waterColor, 1.0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              #include <tonemapping_fragment>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        #include <colorspace_fragment>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              this.mesh = new THREE.Mesh(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    geometry,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          material
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  this.mesh.rotation.x = -Math.PI / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      this.mesh.position.y = -0.8;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          scene.add(this.mesh);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              update(time) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  this.uniforms.uTime.value = time;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dispose() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          this.mesh.geometry.dispose();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              this.mesh.material.dispose();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                